INSERT INTO resena (resena_id, usuario_id, obra_id, calificacion, texto, oculta, creado_en, actualizado_en) VALUES
    ('d1000000-0000-4000-8000-000000000001', 'c1000000-0000-4000-8000-000000000002', 'b1000000-0000-4000-8000-000000000001', 5, 'Una obra maestra de la ciencia ficción: política, religión y ecología en un solo desierto.', false, '2026-11-03T18:00:00Z', '2026-11-03T18:00:00Z'),
    ('d1000000-0000-4000-8000-000000000002', 'c1000000-0000-4000-8000-000000000004', 'b1000000-0000-4000-8000-000000000001', 4, 'Denso al principio, pero la segunda mitad lo compensa.', false, '2026-11-05T20:00:00Z', '2026-11-05T20:00:00Z'),
    ('d1000000-0000-4000-8000-000000000003', 'c1000000-0000-4000-8000-000000000005', 'b1000000-0000-4000-8000-000000000001', 4, 'Imprescindible, aunque el final llega de golpe.', false, '2026-11-06T21:00:00Z', '2026-11-06T21:00:00Z'),
    ('d1000000-0000-4000-8000-000000000004', 'c1000000-0000-4000-8000-000000000002', 'b1000000-0000-4000-8000-000000000003', 4, 'Divertido y muy riguroso. Watney tiene mucha personalidad.', false, '2026-11-04T19:00:00Z', '2026-11-04T19:00:00Z'),
    ('d1000000-0000-4000-8000-000000000005', 'c1000000-0000-4000-8000-000000000007', 'b1000000-0000-4000-8000-000000000003', 5, 'No pude soltarlo. Ciencia y humor a partes iguales.', false, '2026-11-07T22:00:00Z', '2026-11-07T22:00:00Z'),
    ('d1000000-0000-4000-8000-000000000006', 'c1000000-0000-4000-8000-000000000005', 'b1000000-0000-4000-8000-000000000004', 5, 'Un relato breve que cambia cómo se piensa el tiempo.', false, '2026-11-08T17:00:00Z', '2026-11-08T17:00:00Z'),
    ('d1000000-0000-4000-8000-000000000007', 'c1000000-0000-4000-8000-000000000003', 'b1000000-0000-4000-8000-000000000005', 5, 'Más tenso y más oscuro que la película.', false, '2026-11-02T16:00:00Z', '2026-11-02T16:00:00Z'),
    ('d1000000-0000-4000-8000-000000000008', 'c1000000-0000-4000-8000-000000000007', 'b1000000-0000-4000-8000-000000000005', 4, 'Muy entretenido; la parte técnica se hace larga.', false, '2026-11-09T18:30:00Z', '2026-11-09T18:30:00Z'),
    ('d1000000-0000-4000-8000-000000000009', 'c1000000-0000-4000-8000-000000000002', 'b1000000-0000-4000-8000-000000000006', 3, 'Agradable, pero esperaba más de la aventura.', false, '2026-11-04T21:00:00Z', '2026-11-04T21:00:00Z'),
    ('d1000000-0000-4000-8000-000000000010', 'c1000000-0000-4000-8000-000000000004', 'b1000000-0000-4000-8000-000000000008', 4, 'Ingenioso y mordaz; los diálogos siguen funcionando.', false, '2026-11-10T19:00:00Z', '2026-11-10T19:00:00Z'),
    ('d1000000-0000-4000-8000-000000000011', 'c1000000-0000-4000-8000-000000000002', 'b1000000-0000-4000-8000-000000000009', 5, 'Cuidado: este comentario revela el final de la novela.', true, '2026-11-11T20:00:00Z', '2026-11-11T20:00:00Z'),
    ('d1000000-0000-4000-8000-000000000012', 'c1000000-0000-4000-8000-000000000008', 'b1000000-0000-4000-8000-000000000009', 2, 'Bien escrito, pero frío y previsible.', false, '2026-11-12T20:00:00Z', '2026-11-12T20:00:00Z'),
    ('d1000000-0000-4000-8000-000000000013', 'c1000000-0000-4000-8000-000000000006', 'f1000000-0000-4000-8000-000000000001', 4, 'Visualmente impresionante.', false, '2026-11-13T21:00:00Z', '2026-11-13T21:00:00Z'),
    ('d1000000-0000-4000-8000-000000000014', 'c1000000-0000-4000-8000-000000000004', 'f1000000-0000-4000-8000-000000000001', 3, 'Bella, pero deja fuera mucho de la política del libro.', false, '2026-11-14T22:00:00Z', '2026-11-14T22:00:00Z'),
    ('d1000000-0000-4000-8000-000000000015', 'c1000000-0000-4000-8000-000000000003', 'f1000000-0000-4000-8000-000000000006', 4, 'Sigue siendo una gran película de aventuras.', false, '2026-11-15T20:00:00Z', '2026-11-15T20:00:00Z'),
    ('d1000000-0000-4000-8000-000000000016', 'c1000000-0000-4000-8000-000000000007', 'f1000000-0000-4000-8000-000000000004', 4, 'Fiel al tono del libro.', false, '2026-11-16T21:00:00Z', '2026-11-16T21:00:00Z'),
    ('d1000000-0000-4000-8000-000000000017', 'c1000000-0000-4000-8000-000000000002', 'f1000000-0000-4000-8000-000000000009', 5, 'Una adaptación con mucha atmósfera.', false, '2026-11-17T20:00:00Z', '2026-11-17T20:00:00Z'),
    ('d1000000-0000-4000-8000-000000000018', 'c1000000-0000-4000-8000-000000000008', 'f1000000-0000-4000-8000-000000000010', 3, 'La primera mitad es mejor que la segunda.', false, '2026-11-18T20:00:00Z', '2026-11-18T20:00:00Z');
