-- ARCHIVO GENERADO: no lo edites a mano.
-- Fuente unica: db/semilla/semilla.json. Regenerar con: powershell -File db\semilla\generar.ps1
-- Descripcion y escenarios: db/semilla/README.md
-- Se puede repetir: vacia las tablas y vuelve a cargar. Requiere 01-esquema.sql, 02-indices.sql y 03-trigger.sql.
-- promedio y total_resenas NO se escriben: los calcula el trigger al insertar cada resena (RN-08, RF-13).
-- Las contrasenas son hashes bcrypt (pgcrypto, coste 10); la contrasena de prueba esta en db/semilla/README.md.

\set ON_ERROR_STOP on
SET client_min_messages = warning;

BEGIN;

TRUNCATE sesion, sync_outbox, seguimiento, elemento_lista, lista, estado_obra, resena, obra_resumen, usuario RESTART IDENTITY;


-- Referencia local de cada obra (libros, peliculas y borradores). El promedio queda en NULL y 0 resenas hasta que el trigger lo calcule.

-- Estados de lectura (RF-13: cada resena de abajo tiene aqui su estado "terminada").

-- Resenas: cada INSERT dispara trg_resena_promedio, que recalcula promedio y total_resenas de la obra (no cuenta las ocultas).




COMMIT;

-- Resumen de lo cargado
SELECT 'usuario' AS tabla, count(*) AS filas FROM usuario UNION ALL SELECT 'obra_resumen', count(*) FROM obra_resumen UNION ALL
       SELECT 'resena', count(*) FROM resena UNION ALL SELECT 'estado_obra', count(*) FROM estado_obra UNION ALL
       SELECT 'seguimiento', count(*) FROM seguimiento UNION ALL SELECT 'lista', count(*) FROM lista UNION ALL SELECT 'elemento_lista', count(*) FROM elemento_lista;
